def partition_opt(head, x):
    less_head = less_tail = None
    ge_head = ge_tail = None
    cur = head
    while cur:
        nxt = cur.nxt
        cur.nxt = None
        if cur.v < x:
            if less_head is None:
                less_head = cur
            else:
                less_tail.nxt = cur
            less_tail = cur
